        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 3,
        "verseNumber": 8,
        "text": "They heard Yahweh God’s voice walking in the garden in the cool of the day, and the man and his wife hid themselves from the presence of Yahweh God among the trees of the garden.",
        "translation": "WEB",
