        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 4,
        "verseNumber": 14,
        "text": "Behold, you have driven me out today from the surface of the ground. I will be hidden from your face, and I will be a fugitive and a wanderer in the earth. Whoever finds me will kill me.”",
