        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 4,
        "verseNumber": 15,
        "text": "Yahweh said to him, “Therefore whoever slays Cain, vengeance will be taken on him sevenfold.” Yahweh appointed a sign for Cain, so that anyone finding him would not strike him.",
