        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 12,
        "verseNumber": 12,
        "text": "It will happen, when the Egyptians see you, that they will say, ‘This is his wife.’ They will kill me, but they will save you alive.",
        "translation": "WEB",
        "illustrationId": "ill-gen-12",
        "linkedEntities": []
