        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 14,
        "verseNumber": 10,
        "text": "Now the valley of Siddim was full of tar pits; and the kings of Sodom and Gomorrah fled, and some fell there. Those who remained fled to the hills.",
