        "bookName": "Genesis",
        "chapterNumber": 24,
        "verseNumber": 35,
        "text": "Yahweh has blessed my master greatly. He has become great. Yahweh has given him flocks and herds, silver and gold, male servants and female servants, and camels and donkeys.",
