        "bookName": "Genesis",
        "chapterNumber": 32,
        "verseNumber": 10,
        "text": "I am not worthy of the least of all the loving kindnesses, and of all the truth, which you have shown to your servant; for with just my staff I crossed over this Jordan; and now I have become two companies.",
