        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 39,
        "verseNumber": 15,
        "text": "When he heard that I lifted up my voice and cried, he left his garment by me, and ran outside.”",
        "translation": "WEB",
