        "bookId": "GEN",
        "bookName": "Genesis",
        "chapterNumber": 41,
        "verseNumber": 30,
        "text": "Seven years of famine will arise after them, and all the plenty will be forgotten in the land of Egypt. The famine will consume the land,",
